find:
  justify-content: flex-start;
  gap: var(--hud-space-4);
  padding: var(--hud-space-5);
  overflow-y: auto;
  background: var(--hud-scrim-page);
  color: var(--hud-text);
}

/* Same reason as .hud-about--hidden: without it the pane covers the page from load. */

replace:
  justify-content: center;
  gap: var(--hud-space-4);
  padding: var(--hud-space-5);
  overflow-y: auto;
  background: var(--hud-scrim-page);
  color: var(--hud-text);
}

/* Same reason as .hud-about--hidden: without it the pane covers the page from load. */
